import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import {
  MEMORY_CAP,
  MemoryContract,
  enforceUserMemoryCap,
  memoryWritingInstructions,
  projectMemoryDir,
  rebuildProjectIndex,
  userMemoryFile,
} from '../src/agent/memory/memories'

